!function(){"use strict";var t=document.querySelector("[data-swps-audit-progress]");if(t)var e=window.setInterval(function(){window.fetch(window.ajaxurl+"?action=swps_site_audit_progress&_wpnonce="+t.dataset.nonce).then(function(t){return t.json()}).then(function(n){if(n&&n.success){var o=n.data;t.querySelector(".swps-audit-bar").style.width=o.percent+"%",t.querySelector(".swps-audit-count").textContent=o.done+" / "+o.total,o.finished&&(window.clearInterval(e),window.location.reload())}})},3e3);document.querySelectorAll("[data-swps-copy-urls]").forEach(function(t){t.addEventListener("click",function(){navigator.clipboard.writeText(t.dataset.swpsCopyUrls.split("|").join("\n")).then(function(){t.textContent=t.dataset.copied||"Copied!"})})})}();